def test_real_javascript_obfuscator_base64_rotation() -> None:
    report = js.inspect_javascript(OBFUSCATOR_510)
    assert len(report.string_arrays) == 1
    assert report.string_arrays[0].rotation == 3
    assert report.decoders[0].index_base == 0xA3
    recovered = {(row.argument, row.value) for row in report.decoded_calls}
    assert (0xAB, "CSCTF{offline_js_oracle}") in recovered
    assert (0xAD, "log") in recovered


def _reference_rc4_encode(text: str, key: str) -> str:
    """Small independent reference encoder, intentionally not using engine code."""
    box = list(range(256))
    key_bytes = key.encode()
    j = 0
    for i in range(256):
        j = (j + box[i] + key_bytes[i % len(key_bytes)]) & 0xFF
        box[i], box[j] = box[j], box[i]
    i = j = 0
    output = bytearray()
    for byte in text.encode():
        i = (i + 1) & 0xFF
        j = (j + box[i]) & 0xFF
        box[i], box[j] = box[j], box[i]
        output.append(byte ^ box[(box[i] + box[j]) & 0xFF])
    standard = base64.b64encode(output).decode().rstrip("=")
    standard_alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    obfuscator_alphabet = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789+/"
    return standard.translate(str.maketrans(standard_alphabet, obfuscator_alphabet))


def test_rc4_uses_independent_reference_encoder() -> None:
    encoded = _reference_rc4_encode("CSCTF{rc4_string_array}", "grid-key")
    source = f"""
    function table() {{
      const values = ['{encoded}'];
      table = function() {{ return values; }};
      return table();
    }}
    function decode(index, key) {{
      index = index - 0x40;
      const values = table(); let value = values[index];
      function marker(x) {{ decodeURIComponent(x); x.charCodeAt(0); return 256; }}
      return value;
    }}
    const answer = decode(0x40, 'grid-key');
    """
    report = js.inspect_javascript(source)
    assert report.decoders[0].encoding == "rc4"
    assert any(row.value == "CSCTF{rc4_string_array}" for row in report.decoded_calls)


def test_webpack5_chunk_registry_extraction() -> None:
    source = r'''(self["webpackChunkgrid"]=self["webpackChunkgrid"]||[]).push([
      [42], {
        101: function(module,exports,__webpack_require__) {
          const x = "CSCTF{webpack_module}"; __webpack_require__(7);
        },
        202: (module) => { module.exports = "power-grid"; }
      }
    ]);'''
    report = js.inspect_javascript(source)
    assert [(row.module_id, row.chunk_ids) for row in report.webpack_modules] == [
        ("101", ("42",)), ("202", ("42",))
    ]
    assert report.webpack_modules[0].strings == ("CSCTF{webpack_module}",)
    assert report.webpack_modules[0].requires == ("7",)
    assert len(report.webpack_modules[0].sha256) == 64


@pytest.mark.parametrize("bad", [
    b"\xff\xfe",
    "const a = ['unterminated'",
    "const a = ['x']; function d(i){i=i-1; const q=a[i]; return q;",  # cut body
    17,
])
def test_malformed_input_exposes_only_declared_error(bad) -> None:
    with pytest.raises(js.RedepthJSError):
        js.inspect_javascript(bad)


def test_cli_guard_and_no_dynamic_execution(tmp_path, capsys) -> None:
    sample = tmp_path / "bundle.js"
    sample.write_text(OBFUSCATOR_510, encoding="utf-8")
    assert js.main([str(sample), "--compact"]) == 0
    payload = json.loads(capsys.readouterr().out)
    assert any(row["value"] == "CSCTF{offline_js_oracle}"
               for row in payload["decoded_calls"])
    assert js.main(["--does-not-exist"]) == 2
    tree = ast.parse(Path(js.__file__).read_text())
    banned = {"eval", "exec", "compile"}
    assert not [node for node in ast.walk(tree)
                if isinstance(node, ast.Call) and isinstance(node.func, ast.Name)
                and node.func.id in banned]
